export {
  ScrollArea,
  ScrollAreaViewport,
  ScrollAreaContent,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaCorner,
} from "./scroll-area";

import { tv, type VariantProps } from "tailwind-variants";

const scrollArea = tv({
  slots: {
    root: "relative flex min-h-0 max-w-[calc(100vw-3rem)] flex-auto",
    viewport: [
      "min-h-0 flex-auto outline-none focus-visible:ring-2 focus-visible:ring-ring",
    ],
    content: "flex flex-col pe-3 text-sm text-foreground",
    scrollbar: [
      "pointer-events-none m-px flex rounded-full bg-muted opacity-0 transition-opacity duration-300 ease-default",
      "data-hovering:pointer-events-auto data-hovering:opacity-100",
      "data-scrolling:pointer-events-auto data-scrolling:opacity-100 data-scrolling:duration-0",
      "data-[orientation=horizontal]:h-1.5",
      "data-[orientation=vertical]:w-1.5 data-[orientation=vertical]:justify-center",
    ],
    thumb: [
      "w-full rounded-full bg-primary",
      "data-[orientation=horizontal]:h-full",
    ],
    corner: "",
  },
  variants: {
    faded: {
      false: {},
      true: {
        viewport:
          "mask-linear-[to_bottom,transparent_0,black_min(40px,var(--scroll-area-overflow-y-start)),black_calc(100%-min(40px,var(--scroll-area-overflow-y-end,40px))),transparent_100%] mask-no-repeat",
      },
    },
  },
  defaultVariants: {
    faded: false,
  },
});

type ScrollAreaVariantProps = VariantProps<typeof scrollArea>;

export { scrollArea };
export type { ScrollAreaVariantProps };

"use client";

import { useDirection } from "@base-ui/react";
import { ScrollArea as BaseScrollArea } from "@base-ui/react/scroll-area";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { scrollArea, type ScrollAreaVariantProps } from "./scroll-area.style";

type ScrollAreaContext = ScrollAreaVariantProps;

const ScrollAreaContext = createContext<ScrollAreaContext>({
  faded: false,
});

function useScrollArea() {
  return useContext(ScrollAreaContext);
}

function ScrollArea({
  faded,
  className,
  children,
  ...props
}: BaseScrollArea.Root.Props & ScrollAreaVariantProps) {
  const direction = useDirection();

  return (
    <ScrollAreaContext.Provider value={{ faded }}>
      <BaseScrollArea.Root
        data-slot="scroll-area"
        className={mergeSlotClassName(scrollArea().root, className)}
        {...props}
        dir={direction}
      >
        {children}
      </BaseScrollArea.Root>
    </ScrollAreaContext.Provider>
  );
}

function ScrollAreaViewport({
  className,
  ...props
}: BaseScrollArea.Viewport.Props) {
  const { faded } = useScrollArea();

  return (
    <BaseScrollArea.Viewport
      data-slot="scroll-area-viewport"
      className={mergeSlotClassName(scrollArea({ faded }).viewport, className)}
      {...props}
    />
  );
}

function ScrollAreaContent({
  className,
  ...props
}: BaseScrollArea.Content.Props) {
  return (
    <BaseScrollArea.Content
      data-slot="scroll-area-content"
      className={mergeSlotClassName(scrollArea().content, className)}
      {...props}
    />
  );
}

function ScrollAreaScrollbar({
  className,
  ...props
}: BaseScrollArea.Scrollbar.Props) {
  return (
    <BaseScrollArea.Scrollbar
      data-slot="scroll-area-scrollbar"
      className={mergeSlotClassName(scrollArea().scrollbar, className)}
      {...props}
    />
  );
}

function ScrollAreaThumb({ className, ...props }: BaseScrollArea.Thumb.Props) {
  return (
    <BaseScrollArea.Thumb
      data-slot="scroll-area-thumb"
      className={mergeSlotClassName(scrollArea().thumb, className)}
      {...props}
    />
  );
}

function ScrollAreaCorner({
  className,
  ...props
}: BaseScrollArea.Corner.Props) {
  return (
    <BaseScrollArea.Corner
      data-slot="scroll-area-corner"
      className={mergeSlotClassName(scrollArea().corner, className)}
      {...props}
    />
  );
}

export {
  ScrollArea,
  ScrollAreaViewport,
  ScrollAreaContent,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaCorner,
};
